function overrideBars(){try{if(typeof drawUsageBars==='function'&&!drawUsageBars.__sm534){drawUsageBars=function(canvas,rows){if(!canvas)return;const {ctx,w,h}=setupCanvas(canvas),pr=trendRect(w,h);ctx.clearRect(0,0,w,h);ctx.fillStyle='#101722';ctx.fillRect(0,0,w,h);const max=Math.max(4,...rows.map(r=>r.usage_hours||0)),bw=pr.w/Math.max(1,rows.length);ctx.strokeStyle='rgba(86,134,170,.22)';for(let i=0;i<=4;i++){const y=pr.t+pr.h*i/4;ctx.beginPath();ctx.moveTo(pr.l,y);ctx.lineTo(pr.l+pr.w,y);ctx.stroke()}rows.forEach((r,i)=>{const v=r.usage_hours||0,x=pr.l+i*bw+bw*.16,y=pr.t+(max-v)/max*pr.h;ctx.fillStyle=v>=4?COLORS.teal:COLORS.blue;ctx.fillRect(x,y,bw*.68,pr.t+pr.h-y)});ctx.fillStyle=COLORS.text;ctx.font='9px Segoe UI';const step=Math.max(1,Math.ceil(rows.length/6));rows.forEach((r,i)=>{if(i%step&&i!==rows.length-1)return;const txt=trendDateLabel(r),tw=ctx.measureText(txt).width,x=trendBarX(i,rows.length,pr);ctx.fillText(txt,Math.max(pr.l,Math.min(pr.l+pr.w-tw,x-tw/2)),h-8)});canvas._trendMeta={kind:'usage',rows,xPositions:rows.map((_,i)=>trendBarX(i,rows.length,pr))};wireTrendCanvas(canvas,rows,'usage')};drawUsageBars.__sm534=true}if(typeof drawEventBars==='function'&&!drawEventBars.__sm534){drawEventBars=function(canvas,rows){if(!canvas)return;const {ctx,w,h}=setupCanvas(canvas),pr=trendRect(w,h),types=['OA','CA','H','RERA'],totals=rows.map(r=>types.reduce((n,k)=>n+(r.event_index?.[k]||0),0)),max=Math.max(.1,...totals),bw=pr.w/Math.max(1,rows.length);ctx.clearRect(0,0,w,h);ctx.fillStyle='#101722';ctx.fillRect(0,0,w,h);ctx.strokeStyle='rgba(86,134,170,.22)';for(let i=0;i<=4;i++){const y=pr.t+pr.h*i/4;ctx.beginPath();ctx.moveTo(pr.l,y);ctx.lineTo(pr.l+pr.w,y);ctx.stroke()}rows.forEach((r,i)=>{let y=pr.t+pr.h;for(const k of types){const v=r.event_index?.[k]||0,hh=v/max*pr.h;if(!hh)continue;ctx.fillStyle=EVENT_COLORS[k];ctx.fillRect(pr.l+i*bw+bw*.14,y-hh,bw*.72,hh);y-=hh}});ctx.font='10px Segoe UI';drawLegend(ctx,pr,types.map(k=>({name:k,color:EVENT_COLORS[k]})));ctx.fillStyle=COLORS.text;const step=Math.max(1,Math.ceil(rows.length/6));rows.forEach((r,i)=>{if(i%step&&i!==rows.length-1)return;const txt=trendDateLabel(r),tw=ctx.measureText(txt).width,x=trendBarX(i,rows.length,pr);ctx.fillText(txt,Math.max(pr.l,Math.min(pr.l+pr.w-tw,x-tw/2)),h-8)});canvas._trendMeta={kind:'events',rows,xPositions:rows.map((_,i)=>trendBarX(i,rows.length,pr))};wireTrendCanvas(canvas,rows,'events')};drawEventBars.__sm534=true}requestAnimationFrame(()=>{try{drawDashboardTrends()}catch{}})}catch{}}
